"""``render_all()``: every generated file in memory; ``build`` writes them to ``generated/`` (FR-1, FR-2).

``check`` compares the same dictionary with the disk, so generated files cannot drift from ``build``.
"""

from __future__ import annotations

from pathlib import Path

from domain_model.model import Domain
from domain_model.rdf.owl import owl_graph
from domain_model.rdf.serialize import serialize
from domain_model.rdf.shacl import shacl_graph
from domain_model.rdf.skos import skos_graph
from domain_model.text.markdown import glossary_md, level_md, rules_md, statements_md
from domain_model.text.mermaid import diagrams_md
from domain_model.text.tbx import glossary_tbx

GENERATED = "generated"


def _header(source: str) -> str:
    return f"Generated by domain-model from {source}. Do not edit."


def render_all(domain: Domain) -> dict[str, bytes]:
    """Every file of the spec's "Generated" table, keyed by its name inside ``generated/``."""
    owl, skos, shacl = owl_graph(domain), skos_graph(domain), shacl_graph(domain)
    onto_header = _header("ontology.yaml and ontology.axioms.ttl")
    files = {
        "statements.md": statements_md(domain).encode(),
        "glossary.md": glossary_md(domain).encode(),
        "glossary.tbx": glossary_tbx(domain),
        "taxonomy.skos.ttl": serialize(skos, "turtle", _header("ontology.yaml (parent, also_parents)")),
        "ontology.owl.ttl": serialize(owl, "turtle", onto_header),
        "ontology.owl.rdf": serialize(owl, "xml", onto_header),
        "ontology.jsonld": serialize(owl, "json-ld", onto_header),
        "rules.md": rules_md(domain).encode(),
        "rules.shacl.ttl": serialize(shacl, "turtle", _header("the rules in ontology.yaml")),
        "diagrams.md": diagrams_md(domain).encode(),
    }
    for level in (1, 2, 3):
        files[f"level-{level}.md"] = level_md(domain, level).encode()
    return dict(sorted(files.items()))


def write_generated(folder: Path, files: dict[str, bytes]) -> None:
    """Write ``files`` to ``<folder>/generated/`` and remove every other file there."""
    target = folder / GENERATED
    target.mkdir(exist_ok=True)
    for path in sorted(target.rglob("*"), reverse=True):
        if path.is_file() and str(path.relative_to(target)) not in files:
            path.unlink()
        elif path.is_dir() and not any(path.iterdir()):
            path.rmdir()
    for name, data in files.items():
        path = target / name
        if not path.is_file() or path.read_bytes() != data:
            path.write_bytes(data)
